const zone = document.createElement('div');
zone.addEventListener('pointerdown', e => {
  startDrag(e, {
    threshold: 3,
    onMove: ({ dx, dy }) => { zone.style.translate = `${dx}px ${dy}px`; },
    onEnd: ({ dragged }) => { if (!dragged) zone.focus(); },
    onCancel: () => { zone.style.translate = ''; },
  });
});

const store = createStore({
  key: 'mon-app:items',
  version: 2,
  defaults: { items: [] },
  migrate: (data, from) => (from === 1 ? { items: data } : data),
  validate: data => Array.isArray(data?.items),
});
const { status, data } = store.load();
const resultat = store.save({ items: [...data.items, 'nouveau'] });
if (!resultat.ok && resultat.reason === 'quota') console.warn('stockage plein', status);

